import { BookOpen, Sparkles } from "lucide-react";
import { enchantmentLabel } from "../../lib/parseItem";
import { formatRuneName, romanRuneLevel } from "../../lib/variantPresentation";

export default function ItemDetailsCard({ presentation, observedEnchantments }) {
  const details = presentation?.details || [];
  const observed = (observedEnchantments || []).filter((e) => e && e.name);
  const standardEnchantments = observed.filter(e => !/^oxywire:/i.test(e.name));
  const appliedRunes = observed.filter(e => /^oxywire:/i.test(e.name));
  const hasEnchantments = standardEnchantments.length > 0;
  const hasRunes = appliedRunes.length > 0;
  const hasDetails = details.length > 0;
  if (!hasEnchantments && !hasDetails && !hasRunes) return null;
  const enchantSections = (hasEnchantments ? 1 : 0) + (hasRunes ? 1 : 0);

  return (
    <section
      data-testid="item-details-card"
      aria-labelledby="item-details-heading"
      className="px-6 sm:px-8 pt-6"
    >
      <div className="surface-card relative overflow-hidden p-4 sm:p-5">
        <div className="absolute inset-y-0 left-0 w-0.5 bg-gradient-to-b from-emerald-400 via-emerald-500/70 to-transparent" />
        <div className="min-w-0">
            <div className="flex items-start justify-between gap-4">
              <div>
                <div className="font-mono text-[9px] uppercase tracking-[0.24em] text-emerald-500 dark:text-emerald-400 mb-1.5">
                  Item profile
                </div>
                <h3 id="item-details-heading" className="font-heading text-lg sm:text-xl font-bold text-[var(--text-primary)]">
                  Item details
                </h3>
              </div>
              <BookOpen className="w-4 h-4 text-[var(--text-muted)] shrink-0 mt-1" aria-hidden="true" />
            </div>

            <p className="mt-1 text-xs leading-relaxed text-[var(--text-muted)]">
              {hasEnchantments || hasRunes
                ? "Enchantments observed on market listings; effects and use are server reference information."
                : "Server reference information for this item. Individual listings may differ."}
            </p>

            <div className={`mt-4 grid gap-5 ${enchantSections === 1 && hasDetails ? "lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]" : enchantSections + (hasDetails ? 1 : 0) > 1 ? "lg:grid-cols-2" : ""}`}>
              {hasEnchantments && (
                <div>
                  <h4 className="font-mono text-[10px] uppercase tracking-[0.2em] text-[var(--text-secondary)] inline-flex items-center gap-2 mb-2.5">
                    <Sparkles className="w-3.5 h-3.5 text-amber-500 dark:text-amber-400" aria-hidden="true" />
                    Standard enchantments
                  </h4>
                  <ul className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                    {standardEnchantments.map((enchantment, index) => (
                      <li key={`${enchantment.name}-${index}`} className="flex items-baseline justify-between gap-3 min-w-0 rounded-md border border-[rgb(var(--border-subtle)/0.12)] bg-[rgb(var(--bg-deeper)/0.35)] px-2.5 py-1.5">
                        <span className="text-sm leading-5 text-[var(--text-primary)]">{enchantmentLabel(enchantment.name)}</span>
                        <span className="font-mono text-[11px] tabular-nums text-amber-600 dark:text-amber-400 shrink-0">
                          {(enchantment.levels || []).join(", ")}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {hasRunes && (
                <div>
                  <h4 className="font-mono text-[10px] uppercase tracking-[0.2em] text-[var(--text-secondary)] inline-flex items-center gap-2 mb-2.5">
                    <Sparkles className="w-3.5 h-3.5 text-violet-500 dark:text-violet-400" aria-hidden="true" />
                    Applied runes
                  </h4>
                  <ul className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                    {appliedRunes.map((enchantment, index) => (
                      <li key={`${enchantment.name}-${index}`} className="flex items-baseline justify-between gap-3 min-w-0 rounded-md border border-violet-400/15 bg-violet-400/[0.05] px-2.5 py-1.5">
                        <span className="text-sm leading-5 text-[var(--text-primary)]">{formatRuneName(enchantment.name)}</span>
                        <span className="font-mono text-[11px] tabular-nums text-violet-600 dark:text-violet-400 shrink-0">
                          {(enchantment.levels || []).map(romanRuneLevel).join(", ")}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {hasDetails && (
                <div className={enchantSections > 1 ? "lg:col-span-2" : ""}>
                  <h4 className="font-mono text-[10px] uppercase tracking-[0.2em] text-[var(--text-secondary)] mb-2.5">
                    Effects &amp; use
                  </h4>
                  <ul className={`space-y-2.5 ${enchantSections > 1 ? "lg:grid lg:grid-cols-2 lg:gap-x-5 lg:space-y-0 lg:gap-y-2.5" : ""}`}>
                    {details.map((detail, index) => (
                      <li key={`${detail}-${index}`} className="flex gap-2.5 text-sm leading-6 text-[var(--text-secondary)]">
                        <span className="mt-[9px] w-1.5 h-1.5 rotate-45 bg-emerald-500 shrink-0" aria-hidden="true" />
                        <span>{detail}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
        </div>
      </div>
    </section>
  );
}
