import { ITEM_DETAIL_ENTRIES, RUNESTONE_ENTRIES, SET_GEAR_ENTRIES } from "../content/items";
import { ITEM_IMAGES } from "../content/itemImages";
import { normalizeItemDetailKey, resolveItemImageForItem } from "./itemPresentation";
import { parseItemKey } from "./parseItem";

const setGearKeys = new Set(SET_GEAR_ENTRIES.map((entry) => normalizeItemDetailKey(entry.key)));
const runestoneKeys = new Set(RUNESTONE_ENTRIES.map((entry) => normalizeItemDetailKey(entry.key)));

function categoryFor(entry) {
  const key = normalizeItemDetailKey(entry.key);
  if (setGearKeys.has(key)) return "Set Gear";
  if (runestoneKeys.has(key)) return "Runestone";
  const direct = ITEM_IMAGES[key];
  if (direct?.file?.includes("/unique-relic/")) return "Unique Relic";
  const resolved = resolveItemImageForItem({ key: entry.key });
  if (resolved?.src?.includes("/unique-relic/")) return "Unique Relic";
  return "Server Item";
}

function makeReferenceRow(entry) {
  const parsed = parseItemKey(entry.key);
  return Object.freeze({
    key: entry.key,
    name: parsed.displayName,
    rawName: entry.key,
    tier: parsed.tier,
    modifiers: parsed.modifiers || [],
    category: categoryFor(entry),
    median: 0,
    samples: 0,
    confidence: "unobserved",
    iqrLow: 0,
    iqrHigh: 0,
    trend: "stable",
    lastSeenMs: 0,
    referenceOnly: true,
    searchTerms: [entry.key, ...(entry.aliases || [])].map(normalizeItemDetailKey),
  });
}

export const REFERENCE_ITEM_ROWS = Object.freeze(ITEM_DETAIL_ENTRIES.map(makeReferenceRow));

const referenceByIdentity = new Map();
for (const row of REFERENCE_ITEM_ROWS) {
  for (const identity of row.searchTerms) referenceByIdentity.set(identity, row);
}

export function getReferenceItem(value) {
  return referenceByIdentity.get(normalizeItemDetailKey(value)) || null;
}

export function mergeReferenceItems(liveRows = []) {
  const live = Array.isArray(liveRows) ? liveRows : [];
  const liveKeys = new Set(live.map((row) => normalizeItemDetailKey(row.key)));
  return [
    ...live,
    ...REFERENCE_ITEM_ROWS.filter((row) => !liveKeys.has(normalizeItemDetailKey(row.key))),
  ];
}

