import { parseItemKey } from "./parseItem";

export function shopItemDisplayName(row) {
  const itemName = String(row?.itemName || row?.itemTag || "").trim();
  const displayName = String(row?.displayItemName || "").trim();
  if (!itemName) return displayName || "—";
  if (String(row?.variantKey || "").startsWith("oxy2:")) {
    const parsed = parseItemKey(`${itemName}|v:${row.variantKey}`);
    if (parsed.rarity || parsed.category === "Set Gear") return parsed.displayName;
  }
  if (!displayName) return itemName;

  const itemLower = itemName.toLowerCase();
  const displayLower = displayName.toLowerCase();
  if (itemLower === displayLower) return displayName;
  if (itemLower.startsWith(`${displayLower} `)) {
    return `${displayName}${itemName.slice(displayName.length)}`;
  }
  return itemName;
}
